import { compile } from 'sass';

import { log, r } from './utils';

/**
 * Writes a `.d.ts` next to each CSS module with its class names, so `styles.name` imports are typed exactly and
 * unknown class names fail the type check. The generated files are gitignored.
 */
export async function writeCssModuleTypes() {
  for (const file of new Bun.Glob('src/**/*.module.{css,scss}').scanSync({
    cwd: r(),
  })) {
    const path = r(file);
    const css = file.endsWith('.scss')
      ? compile(path).css
      : await Bun.file(path).text();
    const classNames = new Set<string>();

    for (const [selector] of css
      .replace(/\/\*[\s\S]*?\*\//g, '')
      .matchAll(/[^{}]+(?=\{)/g)) {
      // At-rules (`@media`, `@keyframes`, ...) and `:global(...)` classes aren't module classes
      if (selector.trim().startsWith('@')) continue;

      for (const [, name] of selector
        .replace(/:global\([^)]*\)/g, '')
        .matchAll(/\.(-?[_a-z][\w-]*)/gi))
        classNames.add(name);
    }

    const types = [
      '// Generated by scripts/css-module-types.ts',
      'declare const styles: {',
      ...[...classNames]
        .sort()
        .map((name) => `  readonly ${JSON.stringify(name)}: string;`),
      '};',
      'export default styles;',
      '',
    ].join('\n');
    const typesPath = `${path}.d.ts`;

    if (
      (await Bun.file(typesPath).exists())
      && (await Bun.file(typesPath).text()) === types
    )
      continue;

    await Bun.write(typesPath, types);
    log('PRE', `CSS module types written for ${file}`);
  }
}

if (import.meta.main) await writeCssModuleTypes();
